        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.credentials", "Trust is expensive because mistakes are expensive. I keep people alive long enough to learn that.");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.root", "So. You here to make money, stay alive, or ask the kind of question that wastes both our time?");
        add("screen.cyberneticenhancements.npc.dialogue.fixer.line.values", "A clean route, a quiet drop and a client who pays on time. Those are the only values that keep a city like this from eating itself.");
