        add("message.cyberneticenhancements.sandevistan.unavailable_pose", "Sandevistan cannot engage while dead, spectating, sleeping, riding or gliding.");
        add("message.cyberneticenhancements.sandevistan.maintenance_open", "Close the Ripper Station before engaging the Sandevistan. Maintenance disengages neural acceleration.");
