        add("wiki.cyberneticenhancements.status.shock.intent", "This status is meant to read as electrical seizure, not a generic potion effect.");
        add("wiki.cyberneticenhancements.status.overheat.visual", "Visual identity: flame, ember dust, smoke plumes and heat rings.");
